class LoggedFile:
    def __init__(self, wrapped, logger):
        self.__dict__['_wrapped'] = wrapped      # bypass __setattr__
        self.__dict__['_log'] = logger

    def write(self, data):                       # defined here, so not forwarded
        self._log.info('write %d bytes', len(data))
        return self._wrapped.write(data)

    def __getattr__(self, name):                 # everything else forwards lazily
        return getattr(self.__dict__['_wrapped'], name)

